from config import merge


def test_deep_nesting_and_no_mutation():
    defaults = {
        "server": {
            "http": {"host": "0.0.0.0", "port": 80},
            "ssl": {"enabled": False, "cert": "cert.pem"}
        },
        "debug": True
    }
    defaults_copy = copy_dict = {
        "server": {
            "http": {"host": "0.0.0.0", "port": 80},
            "ssl": {"enabled": False, "cert": "cert.pem"}
        },
        "debug": True
    }

    overrides = {
        "server": {
            "http": {"port": 8080},
            "ssl": {"enabled": True}
        },
        "debug": False,
        "new_key": "val"
    }

    result = merge(defaults, overrides)

    # Verify result
    assert result == {
        "server": {
            "http": {"host": "0.0.0.0", "port": 8080},
            "ssl": {"enabled": True, "cert": "cert.pem"}
        },
        "debug": False,
        "new_key": "val"
    }

    # Verify defaults was not mutated
    assert defaults == defaults_copy
